// 1. Получаем данные из узлов
const leadContext = $("Загрузить полный контекст").first().json;
const runContext = $("Регистрация запуска Оркестратора").first().json;
const aiData = $("Оркестратор").first().json;

let rawOutput = aiData.output || "";
let parsedDecision = {};

// 2. Очистка строки от Markdown (```json ... ```)
if (typeof rawOutput === 'string') {
  // Убираем ```json в начале и ``` в конце, а также лишние пробелы
  rawOutput = rawOutput.replace(/^```json\s*/i, '').replace(/\s*```$/, '').trim();
}

// 3. Парсинг очищенной строки
try {
  parsedDecision = typeof rawOutput === 'string' ? JSON.parse(rawOutput) : rawOutput;
} catch (e) {
  // Если всё равно не распарсилось, сохраняем как текст
  parsedDecision = { 
    reply_to_user: rawOutput,
    orchestrator_summary: "Ошибка парсинга после очистки Markdown",
    route_taken: "error_parsing"
  };
}

// 4. Обработка шагов (инструментов)
const steps = (aiData.intermediateSteps || []).map((s, i) => {
  let observationData;
  try {
    observationData = typeof s.observation === 'string' ? JSON.parse(s.observation) : s.observation;
  } catch (e) {
    observationData = s.observation;
  }

  return {
    step: i + 1,
    tool: s.action?.tool || "no_tool",
    input: s.action?.toolInput?.input || s.action?.toolInput,
    output: observationData
  };
});

// 5. Формируем финальный объект
return {
  lead_id: leadContext.id,
  run_id: runContext.run_id,

  // Берем reply_to_user из распарсенного JSON
  reply_to_user: parsedDecision.reply_to_user || "Не удалось получить текст ответа",
  should_send: parsedDecision.should_send_message !== false,

  // Данные для обновления БД
  route: parsedDecision.route_taken || "unknown",
  summary: parsedDecision.orchestrator_summary || "No summary provided",
  next_step: parsedDecision.final_recommended_next_step || "stay_in_qualification",

  // Логи работы
  steps: steps,
  steps_summary: steps.map(s => s.tool).join(' -> ') || 'direct_answer'
};
